extends Node2D
## A6 Effect A trigger: one hit burst per played "damaged" event (CHANGE-BRIEF §1, rules A1-A6).
## Presentation only: it READS main's state (played_events, pieces, paused, time_scale) and
## never writes it. Every look value lives in res://effects/hit_burst.tscn; this script only
## instances the scene, places it, sets `emitting` and `speed_scale`, and frees it.
##
## A child of Main with process_priority 10, so it runs after main's _process (priority 0) in
## the same frame and sees an impact on the frame _cue_impact plays it (A1).
## The node sits at the origin with z 0, so each burst's own z_index 2 stays absolute.
##
## A3 retrigger = overlap: every event gets a NEW instance; earlier bursts keep playing.
## A4: bursts are children of this node, never of an archer. A reset (R, play again, start)
##     clears main.played_events; this node sees the list shrink and frees every live burst.
## A5: speed_scale follows main.time_scale, and is 0 while main.paused.
## A6: a burst frees itself when its longest emitter (Dust) emits `finished`.

const MainScript = preload("res://game/main.gd")
const HitBurstScene: PackedScene = preload("res://effects/hit_burst.tscn")

const HIT_OFFSET: Vector2 = Vector2(0.0, -40.0) ## base-disc centre -> body (CHANGE-BRIEF §1 "Where")
const LONGEST_EMITTER: String = "Dust"

## Bursts created since start (read by tests; never reset).
var spawned: int = 0

var _main: MainScript
var _read: int = 0 ## how many of main.played_events this node has looked at


func _ready() -> void:
	_main = get_parent() as MainScript


func _process(_delta: float) -> void:
	if _main == null:
		return
	var events: Array[Dictionary] = _main.played_events
	if events.size() < _read:
		clear_bursts()
		_read = 0
	while _read < events.size():
		var ev: Dictionary = events[_read]
		_read += 1
		if String(ev["type"]) == "damaged":
			_spawn(ev)
	var speed: float = _speed()
	for burst: Node in get_children():
		for emitter: Node in burst.get_children():
			(emitter as CPUParticles2D).speed_scale = speed


## Live bursts, oldest first (excludes ones already queued for deletion).
func live_bursts() -> Array[Node2D]:
	var out: Array[Node2D] = []
	for burst: Node in get_children():
		if not burst.is_queued_for_deletion():
			out.append(burst as Node2D)
	return out


func clear_bursts() -> void:
	for burst: Node in get_children():
		remove_child(burst)
		burst.queue_free()


func _speed() -> float:
	return 0.0 if _main.paused else _main.time_scale


func _spawn(ev: Dictionary) -> void:
	var piece: Node2D = _main.pieces.get(ev["unit"])
	if piece == null:
		return
	var burst: Node2D = HitBurstScene.instantiate() as Node2D
	add_child(burst)
	burst.position = piece.position + HIT_OFFSET
	var longest: CPUParticles2D = burst.get_node(LONGEST_EMITTER) as CPUParticles2D
	longest.finished.connect(burst.queue_free)
	var speed: float = _speed()
	for emitter: Node in burst.get_children():
		var e: CPUParticles2D = emitter as CPUParticles2D
		e.speed_scale = speed
		e.emitting = true
	spawned += 1

extends Node2D
## A6 Effect B trigger: one arrow trail per arrow in flight (CHANGE-BRIEF §2, rules B1-B6).
## Presentation only: it READS main's state (_arrows, played_events, paused, time_scale) and
## never writes it. Every look value lives in res://effects/arrow_trail.tscn; this script only
## instances the scene, places it, sets `emitting` and `speed_scale`, and frees it.
##
## A child of Main with process_priority 10, so it runs after main's _process (priority 0) in
## the same frame: it sees an arrow on the frame _cue_arrow adds it, and sees it gone on the
## frame _tick_fx drops it.
## The node sits at the origin with z_index 2 (main.tscn): above the board (z 0) and the pieces
## (z 1); equal to main's _fx_layer, which comes later in the tree, so the drawn arrow, HP pips
## and floaters stay on top of the trail.
##
## B1: a new ArrowTrail per new entry of main._arrows (matched by identity), placed at the
##     arrow's `from` point on its first frame, emitting.
## B2: on later frames it follows the arrow tip (formula of main.gd:718-721). On the frame the
##     arrow leaves main._arrows, emitting stops and the trail stays at its last tip position;
##     it is freed after its longest emitter lifetime (Wisps, 0.7 s) of game time.
## B3: a reset (R, play again, start) clears main.played_events; this node sees the list shrink
##     and frees every trail at once.
## B4 / B6: speed_scale is main.time_scale, and 0 while main.paused; the free timer runs on the
##     same clock. With the tree paused this node does not process, so nothing changes.
## B5: this node never reads or writes `visible`.

const MainScript = preload("res://game/main.gd")
const ArrowTrailScene: PackedScene = preload("res://effects/arrow_trail.tscn")

## Trails created since start (read by tests; never reset).
var spawned: int = 0

var _main: MainScript
var _seen_events: int = 0 ## size of main.played_events last frame (a drop means a reset)
## One entry per live trail: {"arrow": the main._arrows Dictionary, "trail": Node2D,
## "landed": bool, "left": game seconds until the trail is freed (after landing)}.
var _trails: Array[Dictionary] = []


func _ready() -> void:
	_main = get_parent() as MainScript


## The arrow tip, as main._draw_fx draws it (main.gd:718-721).
static func tip_of(arrow: Dictionary) -> Vector2:
	var s: float = clampf(float(arrow["t"]) / MainScript.ARROW_TIME, 0.0, 1.0)
	var from: Vector2 = arrow["from"]
	var to: Vector2 = arrow["to"]
	return from.lerp(to, s) + Vector2(0.0, -MainScript.ARROW_ARC * 4.0 * s * (1.0 - s))


func _process(delta: float) -> void:
	if _main == null:
		return
	var events: Array[Dictionary] = _main.played_events
	if events.size() < _seen_events:
		clear_trails()
	_seen_events = events.size()
	var speed: float = _speed()
	var dt: float = delta * speed
	var keep: Array[Dictionary] = []
	for tr: Dictionary in _trails:
		var trail: Node2D = tr["trail"]
		if tr["landed"]:
			tr["left"] = float(tr["left"]) - dt
			if float(tr["left"]) <= 0.0:
				remove_child(trail)
				trail.queue_free()
				continue
		elif _in_flight(tr["arrow"]):
			trail.position = tip_of(tr["arrow"])
		else:
			tr["landed"] = true
			tr["left"] = _longest_lifetime(trail)
			for emitter: Node in trail.get_children():
				(emitter as GPUParticles2D).emitting = false
		keep.append(tr)
	_trails = keep
	for arrow: Dictionary in _main._arrows:
		if not _tracked(arrow):
			_spawn(arrow)
	for tr: Dictionary in _trails:
		for emitter: Node in (tr["trail"] as Node).get_children():
			(emitter as GPUParticles2D).speed_scale = speed


## Live trails, oldest first.
func live_trails() -> Array[Node2D]:
	var out: Array[Node2D] = []
	for tr: Dictionary in _trails:
		out.append(tr["trail"] as Node2D)
	return out


func clear_trails() -> void:
	for tr: Dictionary in _trails:
		var trail: Node = tr["trail"]
		remove_child(trail)
		trail.queue_free()
	_trails.clear()


func _speed() -> float:
	return 0.0 if _main.paused else _main.time_scale


func _in_flight(arrow: Dictionary) -> bool:
	for a: Dictionary in _main._arrows:
		if is_same(a, arrow):
			return true
	return false


func _tracked(arrow: Dictionary) -> bool:
	for tr: Dictionary in _trails:
		if is_same(tr["arrow"], arrow):
			return true
	return false


func _longest_lifetime(trail: Node) -> float:
	var longest: float = 0.0
	for emitter: Node in trail.get_children():
		longest = maxf(longest, (emitter as GPUParticles2D).lifetime)
	return longest


func _spawn(arrow: Dictionary) -> void:
	var trail: Node2D = ArrowTrailScene.instantiate() as Node2D
	add_child(trail)
	trail.position = arrow["from"]
	var speed: float = _speed()
	for emitter: Node in trail.get_children():
		var e: GPUParticles2D = emitter as GPUParticles2D
		e.speed_scale = speed
		e.emitting = true
	_trails.append({"arrow": arrow, "trail": trail, "landed": false, "left": 0.0})
	spawned += 1

extends RefCounted
## Collects PASS/FAIL checks and writes a timestamped JSON report to <repo>/evidence/.

var name: String = ""
var checks: Array[Dictionary] = []
var started_unix: int = 0


func _init(report_name: String) -> void:
	name = report_name
	started_unix = int(Time.get_unix_time_from_system())


func check(label: String, ok: bool, detail: Variant = "") -> bool:
	checks.append({"check": label, "pass": ok, "detail": str(detail)})
	print("%s  %s%s" % ["PASS" if ok else "FAIL", label, "" if str(detail) == "" else "  (" + str(detail) + ")"])
	return ok


func passed() -> int:
	var n: int = 0
	for c: Dictionary in checks:
		if c["pass"]:
			n += 1
	return n


func all_passed() -> bool:
	return passed() == checks.size() and not checks.is_empty()


## Writes the report and returns the exit code (0 only if every check passed).
func finish(extra: Dictionary = {}) -> int:
	var dir: String = ProjectSettings.globalize_path("res://").path_join("../evidence").simplify_path()
	DirAccess.make_dir_recursive_absolute(dir)
	var path: String = dir.path_join("%s-%d.json" % [name, started_unix])
	var data: Dictionary = {
		"report": name,
		"unix_time": started_unix,
		"engine": Engine.get_version_info().get("string", ""),
		"passed": passed(),
		"total": checks.size(),
		"all_passed": all_passed(),
		"checks": checks,
	}
	data.merge(extra)
	var f: FileAccess = FileAccess.open(path, FileAccess.WRITE)
	if f != null:
		f.store_string(JSON.stringify(data, "\t"))
		f.close()
	print("SUMMARY %s: %d/%d passed -> %s" % [name, passed(), checks.size(), path])
	return 0 if all_passed() else 1

extends SceneTree
## A6 headless test: Effect A (hit burst) state rules A1-A6 (CHANGE-BRIEF §1 "Observable rules", §4).
## ./scripts/run-test.sh test_hit_burst_state.gd 60
##
## Drives main.tscn through the real game loop with real key presses (root.push_input); the
## trigger (HitBurstDriver) is never called directly. A Sampler node with process_priority 1000
## records one row per frame, after main (0) and the driver (10): the "damaged" events that
## main played in that frame (the oracle, read from main.played_events) and every live burst.
##
## Run 1 ("win"): title (load) -> win route (tests/fixtures/win_route.json). Turn 4: two hits,
##   enemy first, 1.05 s apart; turn 5: the player's killing hit. Then play again.
## Run 2 ("pause"): win route turns 1-3, then turn 4 with P pause, time_scale 0.5 and a tree
##   pause during the first burst, and R pressed while both bursts of the turn are alive.
## Every hit and start cell the test relies on is asserted from main's event log, not assumed.

const Report = preload("res://tests/test_report.gd")
const Runner = preload("res://tests/route_runner.gd")
const RulesScript = preload("res://game/rules.gd")
const MainScene = preload("res://game/main.tscn")
const BurstScene = preload("res://effects/hit_burst.tscn")

const HIT_OFFSET: Vector2 = Vector2(0.0, -40.0) ## CHANGE-BRIEF §1 "Where"
const POS_EPS: float = 0.01
const HIT_GAP: float = 1.05 ## s between the two impacts of a two-hit turn (CHANGE-BRIEF §1)
const HOLD_FRAMES: int = 120 ## 2 s at 60 fps: longer than a burst's whole life
const MAX_FRAMES: int = 20000


## Records one row per frame, after every other _process() of that frame.
class Sampler extends Node:
	var row_fn: Callable
	var rows: Array[Dictionary] = []

	func _process(delta: float) -> void:
		if row_fn.is_valid():
			rows.append(row_fn.call(delta))


var rep: Report
var main: Variant
var driver: Node2D
var sampler: Sampler
var phase: String = "load"
var fps: int = 0
var _seen: int = 0 ## oracle's read position in main.played_events
var summary: Dictionary = {}


func _initialize() -> void:
	_run()


# ---------------------------------------------------------------- helpers

func _key(code: int) -> void:
	for pressed: bool in [true, false]:
		var ev: InputEventKey = InputEventKey.new()
		ev.keycode = code as Key
		ev.physical_keycode = code as Key
		ev.pressed = pressed
		root.push_input(ev)


func _s() -> String:
	return main.state_name()


func _frames(n: int) -> void:
	for i: int in n:
		await process_frame


func _wait(cond: Callable) -> bool:
	for i: int in MAX_FRAMES:
		if cond.call():
			return true
		await process_frame
	return false


func _cell(id: String) -> Vector2i:
	return RulesScript.cell_of(main.rules.get_unit(id))


## The "damaged" events of event_log from index `from`, as [unit, by, hp_after].
func _damaged_since(from: int) -> Array:
	var out: Array = []
	for i: int in range(from, main.event_log.size()):
		var ev: Dictionary = main.event_log[i]
		if ev["type"] == "damaged":
			out.append([ev["unit"], ev["by"], int(ev["hp_after"])])
	return out


func _killed_since(from: int) -> Array:
	var out: Array = []
	for i: int in range(from, main.event_log.size()):
		if main.event_log[i]["type"] == "killed":
			out.append(main.event_log[i]["unit"])
	return out


## One row per frame (the oracle): new "damaged" events played this frame and every live burst.
func _row(delta: float) -> Dictionary:
	var played: Array[Dictionary] = main.played_events
	var reset: bool = played.size() < _seen
	if reset:
		_seen = 0
	var hits: Array = []
	while _seen < played.size():
		var ev: Dictionary = played[_seen]
		_seen += 1
		if ev["type"] == "damaged":
			var p: Node2D = main.pieces[ev["unit"]]
			hits.append({"unit": ev["unit"], "hp_after": int(ev["hp_after"]), "expect": p.position + HIT_OFFSET})
	var bursts: Array = []
	for b: Node2D in driver.live_bursts():
		var on: Array = []
		var sp: Array = []
		for e: Node in b.get_children():

extends RefCounted
## Shared test helpers: load a route fixture and replay it through Rules alone (no scene, no audio).

const RulesScript = preload("res://game/rules.gd")


static func load_route(path: String) -> Dictionary:
	var text: String = FileAccess.get_file_as_string(path)
	var data: Variant = JSON.parse_string(text)
	if typeof(data) != TYPE_DICTIONARY:
		push_error("cannot parse route fixture %s" % path)
		return {}
	return data


static func move_of(step: Dictionary) -> Vector2i:
	var m: Array = step["move"]
	return Vector2i(int(m[0]), int(m[1]))


static func target_of(step: Dictionary) -> Variant:
	if step["target"] == null:
		return null
	var t: Array = step["target"]
	return Vector2i(int(t[0]), int(t[1]))


## Replays the route on a fresh Rules. Returns {result: Dictionary, events: Array, snapshot: Dictionary,
## turns_played: int, ok: bool, error: String}.
static func play(route: Dictionary, rules: RulesScript = null) -> Dictionary:
	if rules == null:
		rules = RulesScript.new()
	var events: Array = []
	var res: Dictionary = {"result": "none"}
	var played: int = 0
	var error: String = ""
	for step: Dictionary in route["turns"]:
		if rules.result != "none":
			error = "route continues after the game ended"
			break
		events.append_array(rules.resolve_moves({"p1": move_of(step)}))
		var t: Variant = target_of(step)
		var orders: Dictionary = {}
		if t != null:
			if not rules.valid_targets("p1").has(t):
				error = "turn %d: target %s is not valid" % [rules.turn, str(t)]
			orders["p1"] = t
		events.append_array(rules.resolve_attacks(orders))
		res = rules.end_turn()
		played += 1
	return {"result": res, "events": events, "snapshot": rules.snapshot(), "turns_played": played,
		"ok": error == "", "error": error}


## Expected sound triggers for an event list, per the CHANGE-BRIEF map (at most one sound per shot).
static func expected_sounds(events: Array) -> Dictionary:
	var hop: int = 0
	var hit_keys: Dictionary = {}
	var hurt_keys: Dictionary = {}
	var damaged_enemy: int = 0

func state_name() -> String:
	return STATE_NAMES[state]


func selected_target() -> Variant:
	if target_index >= 0 and target_index < targets.size():
		return targets[target_index]
	return null


# ---------------------------------------------------------------- clock

func _process(delta: float) -> void:
	var dt: float = delta * time_scale
	audio.time_scale = time_scale
	_time += delta
	if not paused:
		_clock += dt
		_run_cues()
		for p: PieceScript in pieces.values():
			p.tick(dt)
		_tick_fx(dt)
		if _message_left > 0.0:
			_message_left -= dt
		if _card_lock > 0.0:
			_card_lock -= dt
	_board_layer.queue_redraw()
	_fx_layer.queue_redraw()
	_hud_layer.queue_redraw()


func _schedule(t: float, fn: Callable) -> void:
	var i: int = _cues.size()
	while i > 0 and float(_cues[i - 1]["t"]) > t:
		i -= 1
	_cues.insert(i, {"t": t, "fn": fn})


func _clear_cues() -> void:
	_cues.clear()
	_clock = 0.0


func _run_cues() -> void:
	while not _cues.is_empty() and float(_cues[0]["t"]) <= _clock:
		var c: Dictionary = _cues.pop_front()
		(c["fn"] as Callable).call()


func _tick_fx(dt: float) -> void:
	for f: Dictionary in _floaters:
		f["t"] = float(f["t"]) + dt
	_floaters = _floaters.filter(func(f: Dictionary) -> bool: return float(f["t"]) < FLOAT_TIME)
	for a: Dictionary in _arrows:
		a["t"] = float(a["t"]) + dt
	_arrows = _arrows.filter(func(a: Dictionary) -> bool: return float(a["t"]) < ARROW_TIME)


# ---------------------------------------------------------------- input

func _unhandled_input(event: InputEvent) -> void:
	if not (event is InputEventKey):
		return
	var k: InputEventKey = event as InputEventKey
	if not k.pressed:
		return
	if k.is_echo():
		ignored_echoes += 1 # held keys never act
		get_viewport().set_input_as_handled()
		return
	var action: String = _action_for(k)
	if action == "":
		return
	get_viewport().set_input_as_handled()
	_handle_action(action, k)


func _action_for(event: InputEvent) -> String:
	for action: String in ACTION_ORDER:
		if event.is_action(action):
			return action
	return ""


func _handle_action(action: String, k: InputEventKey) -> void:
	match action:
		"lt_music":
			audio.toggle_music_mute()
			return
		"lt_sfx":
			audio.toggle_sfx_mute()
			return
		"lt_debug":
			debug_footprints = not debug_footprints
			return
	if state == State.TITLE:
		if action == "lt_confirm":
			_start_play()
		else:
			ignored_inputs += 1
		return
	if action == "lt_pause":
		if _in_play():
			_set_paused(not paused)
		elif show_results and (k.keycode == KEY_ESCAPE or k.physical_keycode == KEY_ESCAPE):
			get_tree().quit()
		else:
			ignored_inputs += 1
		return
	if paused:
		ignored_inputs += 1
		return
	if action == "lt_retry":
		_restart(true)
		return
	match state:
		State.PLAN_MOVE:
			if DIRS.has(action):
				_adjust_move(DIRS[action])
			elif action == "lt_confirm":
				_confirm_move(planned_offset)
			elif action == "lt_stay":
				_confirm_move(Vector2i.ZERO)
		State.PLAN_ATTACK:
			if action == "lt_left" or action == "lt_up":
				_cycle_target(-1)
			elif action == "lt_right" or action == "lt_down":
				_cycle_target(1)
			elif action == "lt_confirm":
				_confirm_attack(selected_target())
			elif action == "lt_stay":
				_confirm_attack(null)
		State.WON, State.LOST:
			if action != "lt_confirm" or _card_lock > 0.0:
				ignored_inputs += 1
			elif not show_results:
				show_results = true
			else:
				_restart(false)
		_:
			ignored_inputs += 1 # playback: gameplay input is ignored


func _in_play() -> bool:
	return state in [State.PLAN_MOVE, State.PLAY_MOVES, State.PLAN_ATTACK, State.PLAY_ATTACKS]


func _set_paused(p: bool) -> void:
	paused = p
	audio.set_paused(p)


# ---------------------------------------------------------------- session

func _start_play() -> void:
	rules.reset()
	event_log.clear()
	played_events.clear()
	_build_pieces()
	_begin_plan_move()


## Retry (R) or play again (Enter on results): full reset to turn 1, music from the top.
func _restart(is_retry: bool) -> void:
	if is_retry:
		retries += 1
	else:
		retries = 0
	_clear_cues()
	_arrows.clear()

